/* Hotel CRM / property management: front desk, rooms, guests, housekeeping, restaurant & kitchen, bar,
   billing, staff (roster, attendance, payroll), income & expenses, WiFi. One property is selected at the top;
   every record carries that hotel's id. Collections are prefixed hc_. */
'use strict';

const HC_ROOM_TYPES = ['Standard', 'Deluxe', 'Suite', 'Family', 'Dormitory'];
const HC_DEPTS = ['Front office', 'Housekeeping', 'Kitchen', 'Service', 'Bar', 'Maintenance', 'Security', 'Accounts'];
const HC_SHIFTS = { M: 'Morning 6–2', E: 'Evening 2–10', N: 'Night 10–6', G: 'General 9–6', OFF: 'Weekly off' };
const HC_ATT = { P: 'Present', H: 'Half day', A: 'Absent', L: 'Leave', WO: 'Weekly off' };
const HC_PAY = ['Cash', 'UPI', 'Card', 'Bank transfer', 'Company credit'];
const HC_EXP = ['Salary', 'Groceries & kitchen', 'Bar purchase', 'Electricity', 'Water', 'Housekeeping supplies', 'Laundry', 'Maintenance & repairs', 'Internet & WiFi', 'Marketing', 'Rent', 'Taxes & licences', 'Other'];
const HC_MENU_CATS = ['Breakfast', 'Starters', 'Main course', 'Rice & biryani', 'Breads', 'Desserts', 'Beverages'];
const HC_BAR_CATS = ['Whisky', 'Rum', 'Vodka', 'Brandy', 'Beer', 'Wine', 'Cocktail', 'Soft drink'];
const HC_TASKS = ['Checkout clean', 'Stay-over clean', 'Deep clean', 'Maintenance', 'Laundry', 'Lost & found', 'Guest request'];
const hcSum = (a, f) => a.reduce((s, x) => s + (+f(x) || 0), 0);
const hcNow = () => new Date().toISOString();

const HC = {
  H: () => Session.get('crmHotel'),
  hotel: () => Store.find('hotels', Session.get('crmHotel')),
  list: k => Store.get('hc_' + k).filter(x => x.hotelId === Session.get('crmHotel')),
  find: (k, id) => Store.find('hc_' + k, id),
  add: (k, doc, prefix = 'HC') => Store.add('hc_' + k, { id: doc.id || genId(prefix, 6), hotelId: Session.get('crmHotel'), createdAt: hcNow(), ...doc }),
  upd: (k, id, patch) => Store.update('hc_' + k, id, patch),
  put(k, id, doc) { this.find(k, id) ? this.upd(k, id, doc) : this.add(k, { id, ...doc }); },
  del: (k, id) => Store.remove('hc_' + k, id),
  cfg() { return { roomGstLow: 5, roomGstHigh: 18, foodGst: 5, barTax: 18, ...(Store.get('hc_settings').find(s => s.id === 'CFG' + Session.get('crmHotel')) || {}) }; },
};
const hcCrud = (el, k, o) => renderCrud(el, { key: 'hc_' + k, rows: () => HC.list(k), defaults: { hotelId: HC.H() }, ...o });
const hcStaffName = id => HC.find('staff', id)?.name || '—';
const hcRoomNo = id => HC.find('rooms', id)?.number || '—';
const hcRoomGst = rate => rate > 7500 ? HC.cfg().roomGstHigh : HC.cfg().roomGstLow;
function hcFolio(stayId) {
  const ch = HC.list('charges').filter(c => c.stayId === stayId), pay = HC.list('payments').filter(p => p.stayId === stayId);
  const sub = hcSum(ch, c => c.amount), tax = hcSum(ch, c => c.amount * (c.gstPct || 0) / 100), total = Math.round(sub + tax), paid = hcSum(pay, p => p.amount);
  return { ch, pay, sub, tax, total, paid, balance: total - paid };
}
const hcFree = (roomId, ci, co, exceptStay) => !HC.list('stays').some(s => s.roomId === roomId && s.id !== exceptStay && ['Reserved', 'Checked-in'].includes(s.status) && s.checkIn < co && ci < s.checkOut);
function hcSubnav(body, key, views, draw) {
  let cur = Session.get('crmSub_' + key); if (!views.some(v => v[0] === cur)) cur = views[0][0];
  body.innerHTML = `<div class="chips" style="margin-bottom:14px">${views.map(([id, l]) => `<button class="chip ${id === cur ? 'on' : ''}" data-sub="${id}">${l}</button>`).join('')}</div><div id="crm-sub"></div>`;
  $$('[data-sub]', body).forEach(b => b.onclick = () => { Session.set('crmSub_' + key, b.dataset.sub); hcSubnav(body, key, views, draw); });
  draw(cur, $('#crm-sub', body));
}

