function hcAddDays(iso, n) { const d = new Date(iso + 'T00:00:00'); d.setDate(d.getDate() + n); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; }
function hcWeekStart(iso) { const d = new Date(iso + 'T00:00:00'); return hcAddDays(iso, -((d.getDay() + 6) % 7)); }

