  for (let n = have; n < nights; n++) HC.add('charges', { stayId: s.id, date: hcAddDays(s.checkIn, n), dept: 'Room', desc: `Room ${hcRoomNo(s.roomId)} · night of ${fmtDate(hcAddDays(s.checkIn, n))}`, amount: +s.rate, gstPct: hcRoomGst(+s.rate) }, 'CH');
