      $('#fo-py', m).onsubmit = e => { e.preventDefault(); const t = e.target; HC.add('payments', { stayId, date: todayISO(), amount: +t.amount.value, method: t.method.value, dept: 'Rooms', note: t.note.value.trim() }, 'PY'); toast('Payment recorded'); after && after(); again(); };
